MEMORY_LEVERS = tuple(n for n, r in LEVERS.items() if r["file"] == f"{ADAPTER}/big.py")   # the memory modes' levers (the engine adapter boltz2_opt.big): xl_report is their evidence


def tier_of(levers) -> int:
    """The tier of a lever list: 2 when any lever is Tier 2, else 1 (an empty list is stock: 0)."""
    if not levers:
        return 0
    return max(LEVERS[n]["tier"] for n in levers)
